import {MarkdownText,MarkdownField} from '../../shared/MarkdownText.jsx';
import {useWritingRequest} from '../../shared/writing-request.js';
import {WritingHistory} from '../../shared/WritingHistory.jsx';
import React,{useState,useEffect} from 'react';
import {useDraft,useResource,usePreference} from '../../shared/state.js';
import {ResourceState,SaveBar} from '../../shared/ui.jsx';
import {Modal} from '../../shared/preferences.tsx';
import {DocumentTextarea} from '../../shared/workspace.tsx';
const states={planned:'计划',planted:'已埋设',developing:'推进中',recovered:'已回收',abandoned:'已放弃'},evidenceKinds={plant:'埋设',progress:'推进',recover:'回收'};
export function Foreshadows({call,novelId,busy,run,onChapter,onMemory,focusId,onFocused}){
 const [selected,setSelected]=usePreference(`${novelId}:foreshadow-selected`,null);
 const [poll,setPoll]=useState(0),[editing,setEditing]=useState(null),[query,setQuery]=useState('');
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)setPoll(n=>n+1);},5000);return()=>clearInterval(timer);},[]);
 const resource=useResource(()=>Promise.all([call('writing.foreshadow.list',{novelId}),call('chapter.list',{novelId}),call('graph.list',{novelId})]),[call,novelId,poll],`${novelId}:foreshadows`);
 useEffect(()=>{if((focusId||selected)&&resource.value){const f=resource.value[0].find(f=>f.id===(focusId||selected));if(f)setEditing(f);setSelected(null);onFocused?.();}},[selected,focusId,resource.value]);
 return <div className="structure-page"><div className="row"><h2 className="grow">伏笔台账</h2><button className="primary" disabled={busy} onClick={()=>setEditing({title:'',content:'',status:'planned',memoryRefs:[],evidence:[],targetChapterId:null,abandonReason:'',revision:0})}>＋ 伏笔</button></div><input aria-label="搜索伏笔" placeholder="搜索伏笔" value={query} onChange={e=>setQuery(e.target.value)}/><ResourceState resource={resource}>{resource.value&&resource.value[0].filter(f=>!query||f.title.includes(query)||f.content.includes(query)).map(f=><div className="structure-entry" key={f.id}><div className="row"><strong className="grow">{f.title}</strong><span>{states[f.status]}</span><button onClick={()=>setEditing(f)}>编辑伏笔</button></div><MarkdownText text={f.content}/>{f.targetChapterId&&<p>计划回收：<button onClick={()=>onChapter(f.targetChapterId)}>{f.targetTitle||'缺失章节'}</button></p>}{f.due&&<p className="notice">已到计划回收章，尚未回收。</p>}{f.review&&<p className="notice">引用正文已改写，需复核。</p>}{f.memoryRefs.map(id=><button key={id} onClick={()=>onMemory(id)}>{resource.value[2].find(n=>n.id===id)?.name||'缺失资料'}</button>)}{f.evidence.map((e,i)=><p key={i}>{evidenceKinds[e.kind]} · <button onClick={()=>onChapter(e.chapterId)}>{resource.value[1].find(c=>c.id===e.chapterId)?.title||'删除章'}</button> · 版本 {e.revision}</p>)}{f.status==='abandoned'&&<p>放弃原因：{f.abandonReason}</p>}</div>)}</ResourceState>{editing&&resource.value&&<ForeshadowEditor {...{call,novelId,busy,run}} initial={editing} chapters={resource.value[1]} nodes={resource.value[2]} close={()=>setEditing(null)} saved={()=>{setEditing(null);setPoll(n=>n+1);}}/>}</div>;
}
export function ForeshadowEditor({call,novelId,busy,run,initial,chapters,nodes,close,saved,event,contextChapterId}){
 const write=useWritingRequest(call);
 const {value:v,base,change,dirty,cacheError,accept}=useDraft(`${novelId}:foreshadow:${initial.id||event?.id||'new'}`,initial),[quote,setQuote]=useState(''),[chapterId,setChapterId]=useState(contextChapterId||''),[evidenceKind,setEvidenceKind]=useState('plant'),[serverError,setServerError]=useState('');
 const set=(key,value)=>change(old=>({...old,[key]:value}));
 const save=()=>run(async()=>{setServerError('');try{const result=await write(initial.id?'writing.foreshadow.update':event?'writing.timelineForeshadow.create':'writing.foreshadow.create',{novelId,id:initial.id,expectedRevision:base.revision,eventId:event?.id,expectedEventRevision:base.contextEventRevision,value:v,confirmed:true,reason:event?'作者从时间节点保存关联伏笔':'作者保存伏笔台账'});accept(initial.id?result:{...initial});saved();}catch(e){setServerError(e.message);throw e;}});
 return <Modal title="编辑伏笔" close={close} className="chapter-materials-modal"><div className="structure-form"><label>名称<input aria-label="伏笔名称" value={v.title} onChange={e=>set('title',e.target.value)}/></label><MarkdownField label="说明" aria-label="伏笔说明" value={v.content} onChange={e=>set('content',e.target.value)}/><label>状态<select aria-label="伏笔状态" value={v.status} onChange={e=>set('status',e.target.value)}>{Object.entries(states).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>计划回收章节<select aria-label="计划回收章节" value={v.targetChapterId||''} onChange={e=>set('targetChapterId',e.target.value||null)}><option value="">未指定</option>{chapters.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select></label><details><summary>关联人物与世界（{v.memoryRefs.length}）</summary><div className="structure-checks">{nodes.map(n=><label key={n.id}><input type="checkbox" checked={v.memoryRefs.includes(n.id)} onChange={e=>set('memoryRefs',e.target.checked?[...v.memoryRefs,n.id]:v.memoryRefs.filter(id=>id!==n.id))}/>{n.name}</label>)}</div></details>{v.status==='abandoned'&&<label>放弃原因<DocumentTextarea aria-label="放弃原因" value={v.abandonReason} onChange={e=>set('abandonReason',e.target.value)}/></label>}
 <h3>正文依据</h3>{v.evidence.map((e,i)=><div className="structure-entry" key={i}><p>{evidenceKinds[e.kind]} · {chapters.find(c=>c.id===e.chapterId)?.title||'删除章'} · 版本 {e.revision}</p><blockquote>{e.evidence}</blockquote><button onClick={()=>set('evidence',v.evidence.filter((_,j)=>j!==i))}>移除此依据</button></div>)}<label>依据类型<select value={evidenceKind} onChange={e=>setEvidenceKind(e.target.value)}>{Object.entries(evidenceKinds).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label>依据章节<select aria-label="伏笔依据章节" value={chapterId} onChange={e=>setChapterId(e.target.value)}><option value="">选择章节</option>{chapters.map(c=><option value={c.id} key={c.id}>{c.title} · 版本 {c.revision}</option>)}</select></label><label>已保存原文<DocumentTextarea aria-label="伏笔正文依据" value={quote} onChange={e=>setQuote(e.target.value)}/></label><button disabled={!chapterId||!quote.trim()} onClick={()=>{const ch=chapters.find(c=>c.id===chapterId);set('evidence',[...v.evidence,{kind:evidenceKind,chapterId,revision:ch.revision,evidence:quote}]);setQuote('');}}>添加正文依据</button><p className="muted">埋设、推进和回收均引用已保存原文。保存时校验，候选不会自动成为事实。</p></div><SaveBar dirty={dirty||!initial.id} {...{busy}} error={serverError||cacheError} invalid={!v.title.trim()?'请填写名称':null} onSave={save} label="保存伏笔"/>{serverError&&event&&!initial.id&&<button disabled={busy} onClick={()=>run(async()=>{const latest=await call('writing.event.get',{novelId,id:event.id});accept({...v,contextEventRevision:latest.revision});setServerError('');})}>保留填写内容并核对最新事件版本</button>}{initial.id&&<WritingHistory chapters={chapters} collection="foreshadows" dirty={dirty} {...{call,novelId,busy,run}} id={initial.id} revision={base.revision} restored={saved}/>}</Modal>;
}
